def is_isbn10(s: str) -> bool:
    s = s.replace("-", "")
    if len(s) != 10:
        return False

    if not all('0' <= c <= '9' for c in s[:9]):
        return False
    if not (('0' <= s[9] <= '9') or s[9] == 'X'):
        return False

    total = 0
    for i, ch in enumerate(s):
        value = 10 if ch == 'X' else int(ch)
        total += value * (10 - i)

    return total % 11 == 0
```

