def evaluate(expr: str):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue

        if c.isdigit() or (c == '.' and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            if i < n and expr[i] == '.':
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            text = expr[start:i]
            if '.' in text:
                val = float(text)
            else:
                val = int(text)
            tokens.append(('num', val))
            continue

        if c == '(':
            tokens.append(('lparen', c))
            i += 1
            continue

        if c == ')':
            tokens.append(('rparen', c))
            i += 1
            continue

        if c in '+-*/%':
            if c == '*' and i + 1 < n and expr[i + 1] == '*':
                tokens.append(('op', '**'))
                i += 2
                continue
            if c == '/' and i + 1 < n and expr[i + 1] == '/':
                tokens.append(('op', '//'))
                i += 2
                continue
            tokens.append(('op', c))
            i += 1
            continue

        raise ValueError(f"Unknown character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def next_token():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        pos += 1
        return tok

    def apply_unary(op, val):
        if op == '-':
            return -val
        if op == '+':
            return +val
        raise ValueError("Unknown unary operator")

    def apply_bin(op, left, right):
        if op == '+':
            return left + right
        if op == '-':
            return left - right
        if op == '*':
            return left * right
        if op == '/':
            return left / right
        if op == '//':
            return left // right
        if op == '%':
            return left % right
        if op == '**':
            return left ** right
        raise ValueError("Unknown operator")

    def get_precedence(op):
        if op in ('+', '-'):
            return 10
        if op in ('*', '/', '//', '%'):
            return 20
        if op == '**':
            return 30
        return -1

    def parse_expression(min_prec):
        left = parse_unary()
        while True:
            tok = peek()
            if tok is None or tok[0] != 'op':
                break
            op = tok[1]
            if op not in ('+', '-', '*', '/', '//', '%', '**'):
                break
            prec = get_precedence(op)
            if prec < min_prec:
                break
            next_token()
            if op == '**':
                right = parse_unary()
                left = apply_bin(op, left, right)
            else:
                right = parse_expression(prec + 1)
                left = apply_bin(op, left, right)
        return left

    def parse_unary():
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] in ('+', '-'):
            op = tok[1]
            next_token()
            val = parse_unary()
            return apply_unary(op, val)
        return parse_power()

    def parse_power():
        left = parse_primary()
        tok = peek()
        if tok is not None and tok[0] == 'op' and tok[1] == '**':
            next_token()
            right = parse_unary()
            left = apply_bin('**', left, right)
        return left

    def parse_primary():
        tok = next_token()
        if tok[0] == 'num':
            return tok[1]
        if tok[0] == 'lparen':
            val = parse_expression(0)
            if peek() is None or peek()[0] != 'rparen':
                raise ValueError("Unbalanced parentheses")
            next_token()
            return val
        raise ValueError("Unexpected token")

    result = parse_expression(0)
    if pos != len(tokens):
        raise ValueError("Unexpected token")
    return result
```

