def invoice_total(items, coupon=None, member=False):
    total = 0
    for item in items:
        qty = item["qty"]
        if qty > 0:
            line_total = item["price"] * qty
            if item["category"] == "food":
                total += line_total
            elif member:
                total += line_total * 0.95
            else:
                total += line_total

    if coupon != None:
        if coupon == "SAVE5":
            if total >= 50:
                total -= 5
        elif coupon == "HALFFOOD":
            food_total = 0
            for item in items:
                if item["qty"] > 0 and item["category"] == "food":
                    food_total += item["price"] * item["qty"]
            total -= food_total / 2
        elif coupon == "BULK10":
            total_qty = sum(item["qty"] for item in items if item["qty"] > 0)
            if total_qty >= 10:
                total *= 0.9
        else:
            raise ValueError("unknown coupon")

    if total < 0:
        total = 0
    return round(total, 2)
```

