import time
from collections import OrderedDict, deque


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if ttl <= 0:
            raise ValueError("ttl must be > 0")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()  # key -> (value, expire_at)
        self.expiry_queue = deque()  # (expire_at, key)

    def _purge_expired(self, now: float) -> None:
        while self.expiry_queue and self.expiry_queue[0][0] <= now:
            exp, key = self.expiry_queue.popleft()
            entry = self.cache.get(key)
            if entry is not None and entry[1] == exp:
                del self.cache[key]

    def set(self, key, value) -> None:
        now = self.clock()
        self._purge_expired(now)

        exp = now + self.ttl

        if key in self.cache:
            self.cache[key] = (value, exp)
            self.cache.move_to_end(key)
            self.expiry_queue.append((exp, key))
        else:
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[key] = (value, exp)
            self.expiry_queue.append((exp, key))

    def get(self, key, default=None):
        now = self.clock()
        entry = self.cache.get(key)

        if entry is not None:
            value, exp = entry
            if now >= exp:
                del self.cache[key]
                return default
            self.cache.move_to_end(key)
            return value

        return default

    def delete(self, key) -> bool:
        now = self.clock()
        entry = self.cache.get(key)

        if entry is None:
            return False

        value, exp = entry

        if now >= exp:
            del self.cache[key]
            return False

        del self.cache[key]
        return True

    def __len__(self) -> int:
        now = self.clock()
        self._purge_expired(now)
        return len(self.cache)

    def __contains__(self, key) -> bool:
        now = self.clock()
        entry = self.cache.get(key)

        if entry is None:
            return False

        value, exp = entry

        if now >= exp:
            del self.cache[key]
            return False

        return True
