def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            i += 1
            chars = []
            closed = False

            while i < n:
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                else:
                    chars.append(line[i])
                    i += 1

            if not closed:
                raise ValueError("Unclosed quoted field")

            if i < n and line[i] != ',':
                raise ValueError("Invalid character after closing quote")

            fields.append(''.join(chars))

            if i < n:
                i += 1
            else:
                break
        else:
            end = line.find(',', i)
            if end == -1:
                fields.append(line[i:])
                break
            fields.append(line[i:end])
            i = end + 1

    return fields
