def is_isbn10(s: str) -> bool:
    clean = s.replace('-', '')
    if len(clean) != 10:
        return False

    total = 0
    for i, ch in enumerate(clean):
        if i == 9:
            if ch == 'X':
                val = 10
            elif '0' <= ch <= '9':
                val = int(ch)
            else:
                return False
        else:
            if not ('0' <= ch <= '9'):
                return False
            val = int(ch)
        total += val * (10 - i)

    return total % 11 == 0
