from heapq import heappush, heappop

def cheapest_route(flights, src, dst, max_stops):
    if src == dst:
        return (0, [src])

    adj = {}
    for o, d, p in flights:
        adj.setdefault(o, []).append((d, p))

    max_flights = max_stops + 1
    heap = [(0, 0, (src,), 0, src, frozenset({src}))]
    counter = 1

    while heap:
        price, flights_used, airports, _, current, visited = heappop(heap)

        if current == dst:
            return (price, list(airports))

        if flights_used >= max_flights:
            continue

        for nxt, p in adj.get(current, []):
            if nxt in visited:
                continue
            heappush(
                heap,
                (price + p, flights_used + 1, airports + (nxt,), counter, nxt, visited | {nxt})
            )
            counter += 1

    return None
