def evaluate(expr: str):
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue

        if c.isdigit() or (c == '.' and i + 1 < n and expr[i + 1].isdigit()):
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            if i < n and expr[i] == '.':
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            if i < n and expr[i] == '.':
                raise ValueError("malformed number")
            text = expr[start:i]
            tokens.append(('NUM', float(text) if '.' in text else int(text), start))
            continue

        if c in '+-*/%':
            if c == '/' and i + 1 < n and expr[i + 1] == '/':
                tokens.append(('OP', '//', i))
                i += 2
            elif c == '*' and i + 1 < n and expr[i + 1] == '*':
                tokens.append(('OP', '**', i))
                i += 2
            else:
                tokens.append(('OP', c, i))
                i += 1
            continue

        if c == '(':
            tokens.append(('LPAREN', '(', i))
            i += 1
            continue

        if c == ')':
            tokens.append(('RPAREN', ')', i))
            i += 1
            continue

        raise ValueError(f"invalid character at position {i}")

    tokens.append(('EOF', None, n))
    pos = 0

    def peek():
        return tokens[pos]

    def parse_expression():
        nonlocal pos
        val = parse_term()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in ('+', '-'):
                op = tok[1]
                pos += 1
                rhs = parse_term()
                val = val + rhs if op == '+' else val - rhs
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_factor()
        while True:
            tok = peek()
            if tok[0] == 'OP' and tok[1] in ('*', '/', '//', '%'):
                op = tok[1]
                pos += 1
                rhs = parse_factor()
                if op == '*':
                    val = val * rhs
                elif op == '/':
                    val = val / rhs
                elif op == '//':
                    val = val // rhs
                else:
                    val = val % rhs
            else:
                break
        return val

    def parse_factor():
        nonlocal pos
        tok = peek()
        if tok[0] == 'OP' and tok[1] in ('+', '-'):
            op = tok[1]
            pos += 1
            val = parse_factor()
            return -val if op == '-' else +val
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_atom()
        tok = peek()
        if tok[0] == 'OP' and tok[1] == '**':
            pos += 1
            exp = parse_factor()
            return base ** exp
        return base

    def parse_atom():
        nonlocal pos
        tok = peek()
        if tok[0] == 'NUM':
            pos += 1
            return tok[1]
        if tok[0] == 'LPAREN':
            pos += 1
            val = parse_expression()
            closing = peek()
            if closing[0] != 'RPAREN':
                raise ValueError("missing closing parenthesis")
            pos += 1
            return val
        raise ValueError("unexpected token")

    result = parse_expression()
    if peek()[0] != 'EOF':
        raise ValueError("unexpected token")
    return result
