import heapq
from collections import defaultdict

def build_order(deps: dict[str, list[str]]) -> list[str]:
    nodes = set(deps)
    reverse = defaultdict(set)
    indegree = {}

    for target, requirements in deps.items():
        unique_requirements = set(requirements)
        nodes.add(target)
        indegree[target] = len(unique_requirements)

        for requirement in unique_requirements:
            nodes.add(requirement)
            reverse[requirement].add(target)

    for node in nodes:
        if node not in indegree:
            indegree[node] = 0

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        for dependent in reverse.get(node, []):
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("dependencies contain a cycle")

    return result
