def parse_csv_line(line: str) -> list[str]:
    result = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            i += 1
            chars = []
            closed = False

            while i < n:
                ch = line[i]
                if ch == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(ch)
                    i += 1

            if not closed:
                raise ValueError("Unclosed quoted field")

            if i < n and line[i] != ',':
                raise ValueError("Expected comma after closing quote")

            result.append(''.join(chars))

            if i < n:
                i += 1
            else:
                return result

        else:
            comma = line.find(',', i)
            end = n if comma == -1 else comma
            result.append(line[i:end])
            i = end

            if i < n:
                i += 1
            else:
                return result
