from collections import OrderedDict, deque

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.od = OrderedDict()  # key -> (value, expire_at)
        self.expiry_queue = deque()  # (expire_at, key)

    def _purge_expired(self, now: float) -> None:
        while self.expiry_queue:
            exp, key = self.expiry_queue[0]
            if exp > now:
                break
            self.expiry_queue.popleft()
            entry = self.od.get(key)
            if entry is not None and entry[1] == exp:
                del self.od[key]

    def set(self, key, value) -> None:
        now = self.clock()
        self._purge_expired(now)
        exp = now + self.ttl

        if key in self.od:
            self.od[key] = (value, exp)
            self.od.move_to_end(key)
        else:
            if len(self.od) >= self.capacity:
                lru_key = next(iter(self.od))
                del self.od[lru_key]
            self.od[key] = (value, exp)

        self.expiry_queue.append((exp, key))

    def get(self, key, default=None):
        now = self.clock()
        entry = self.od.get(key)

        if entry is not None and entry[1] > now:
            value = entry[0]
            self.od.move_to_end(key)
            return value

        if entry is not None:
            del self.od[key]

        return default

    def delete(self, key) -> bool:
        now = self.clock()
        entry = self.od.get(key)

        if entry is not None and entry[1] > now:
            del self.od[key]
            return True

        if entry is not None:
            del self.od[key]

        return False

    def __len__(self) -> int:
        now = self.clock()
        self._purge_expired(now)
        return len(self.od)

    def __contains__(self, key) -> bool:
        now = self.clock()
        entry = self.od.get(key)
        return entry is not None and entry[1] > now
